import hashlib
import hmac
import os
import time
import secrets
from functools import wraps
from flask import Flask, request, jsonify, session
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', secrets.token_hex(32))

SERVICE_SHARED_KEY = os.environ.get('SERVICE_KEY')
if not SERVICE_SHARED_KEY:
    raise RuntimeError(
        'SERVICE_KEY environment variable must be set to a strong secret. '
        'Refusing to start with an insecure default key.'
    )

UPLOAD_FOLDER = '/tmp/uploads'
ALLOWED_EXTENSIONS = {'txt', 'csv', 'json', 'xml'}
os.makedirs(UPLOAD_FOLDER, exist_ok=True)

active_sessions = {}


def compute_service_token(user_id, timestamp, nonce):
    """Compute HMAC token for cross-service authentication."""
    message = f"{user_id}:{timestamp}:{nonce}"
    return hmac.new(
        SERVICE_SHARED_KEY.encode(),
        message.encode(),
        hashlib.sha256
    ).hexdigest()


def validate_service_token(user_id, timestamp, nonce, token):
    """Validate incoming service token with replay protection."""
    current_time = int(time.time())
    if abs(current_time - int(timestamp)) > 300:
        return False
    expected = compute_service_token(user_id, timestamp, nonce)
    return hmac.compare_digest(expected, token)


def bind_session_to_request(user_id, provided_session_id=None):
    """Bind or create a session for the authenticated user.

    Sessions are always generated server-side to prevent
    session fixation attacks in cross-service workflows.
    Client-provided session IDs are only used for lookup.
    """
    if provided_session_id and provided_session_id in active_sessions:
        entry = active_sessions[provided_session_id]
        if entry['user_id'] == user_id:
            entry['last_access'] = time.time()
            return provided_session_id

    session_id = secrets.token_urlsafe(32)

    active_sessions[session_id] = {
        'user_id': user_id,
        'created': time.time(),
        'last_access': time.time(),
        'files': [],
        'permissions': set()
    }
    return session_id


def require_service_auth(f):
    """Decorator for cross-service authenticated endpoints."""
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('X-Service-Auth')
        if not auth_header:
            return jsonify({'error': 'Missing service auth'}), 401

        try:
            parts = auth_header.split(':')
            if len(parts) != 4:
                return jsonify({'error': 'Malformed auth header'}), 401
            user_id, timestamp, nonce, token = parts
        except ValueError:
            return jsonify({'error': 'Invalid auth format'}), 401

        if not validate_service_token(user_id, timestamp, nonce, token):
            return jsonify({'error': 'Invalid service token'}), 403

        session_id = request.headers.get('X-Session-Id')
        bound_session = bind_session_to_request(user_id, session_id)

        request.current_user = user_id
        request.session_id = bound_session
        return f(*args, **kwargs)
    return decorated


def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS


@app.route('/api/v1/upload', methods=['POST'])
@require_service_auth
def upload_file():
    """Handle file upload from authenticated service."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filename = secure_filename(file.filename)
    filepath = os.path.join(UPLOAD_FOLDER, f"{request.session_id}_{filename}")
    file.save(filepath)

    active_sessions[request.session_id]['files'].append({
        'name': filename,
        'path': filepath,
        'uploaded_at': time.time(),
        'size': os.path.getsize(filepath)
    })

    return jsonify({
        'status': 'success',
        'session_id': request.session_id,
        'file': filename
    }), 201


@app.route('/api/v1/files', methods=['GET'])
@require_service_auth
def list_files():
    """List files in the current session."""
    session_data = active_sessions.get(request.session_id, {})
    files = session_data.get('files', [])
    return jsonify({
        'session_id': request.session_id,
        'files': [{'name': f['name'], 'size': f['size']} for f in files]
    })


@app.route('/api/v1/process', methods=['POST'])
@require_service_auth
def process_files():
    """Process all files in the current session."""
    session_data = active_sessions.get(request.session_id)
    if not session_data or not session_data['files']:
        return jsonify({'error': 'No files to process'}), 400

    results = []
    for file_info in session_data['files']:
        with open(file_info['path']) as fh:
            line_count = sum(1 for _ in fh)
        result = {
            'name': file_info['name'],
            'status': 'processed',
            'lines': line_count
        }
        results.append(result)

    return jsonify({'results': results})


@app.route('/api/v1/session/elevate', methods=['POST'])
@require_service_auth
def elevate_session():
    """Grant additional permissions to current session for admin operations."""
    data = request.get_json()
    if not data or 'permission' not in data:
        return jsonify({'error': 'Missing permission field'}), 400

    permission = data['permission']
    allowed_perms = {'read_all', 'write_all', 'admin'}
    if permission not in allowed_perms:
        return jsonify({'error': 'Invalid permission'}), 400

    session_data = active_sessions.get(request.session_id)
    if session_data:
        session_data['permissions'].add(permission)

    return jsonify({'status': 'elevated', 'permissions': list(session_data['permissions'])})


@app.route('/api/v1/admin/sessions', methods=['GET'])
@require_service_auth
def admin_list_sessions():
    """Admin endpoint to list all active sessions."""
    session_data = active_sessions.get(request.session_id)
    if not session_data or 'admin' not in session_data.get('permissions', set()):
        return jsonify({'error': 'Insufficient permissions'}), 403

    all_sessions = {
        sid: {'user_id': data['user_id'], 'files': len(data['files'])}
        for sid, data in active_sessions.items()
    }
    return jsonify({'sessions': all_sessions})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
